class D48:
    def __init__(self, seed):
        self.x = ((seed & 0xFFFFFFFF) << 16) | 0x330E
    def next(self):
        self.x = (0x5DEECE66D * self.x + 0xB) & ((1<<48)-1)
        return self.x
    def drand(self):
        return self.next() / float(1<<48)
